-- CI asserts this file exists; keep it current when the schema changes.


-- ─── brief_records ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS brief_records (
  id                         BIGSERIAL NOT NULL,
  created_at                 TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  company                    TEXT NOT NULL,
  country                    TEXT,
  description                TEXT,
  eligibility                JSONB,
  capital_sought             ARRAY,
  institutions               JSONB NOT NULL,
  dropped_blocked            INTEGER,
  dropped_watch_only         INTEGER,
  candidate_count            INTEGER,
  duration_ms                INTEGER,
  code_version               TEXT,
  outcome                    TEXT,
  outcome_note               TEXT,
  exclusions                 JSONB
);
CREATE INDEX IF NOT EXISTS brief_records_created_idx ON brief_records USING btree (created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS brief_records_pkey ON brief_records USING btree (id);

-- ─── corpus_census ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS corpus_census (
  id                         BIGSERIAL NOT NULL,
  taken_at                   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  produced_by                TEXT NOT NULL,
  code_fingerprint           TEXT NOT NULL,
  kpis                       JSONB,
  instruments                JSONB,
  coverage                   JSONB,
  gate                       JSONB,
  errors                     JSONB NOT NULL DEFAULT '[]'::jsonb,
  run_outcome                TEXT NOT NULL DEFAULT 'unknown'::text,
  -- WHICH STORE this census read, and what it could reach of the committed
  -- migrations. Written by publish_corpus_census.py, which also self-heals them
  -- with ADD COLUMN IF NOT EXISTS -- so until the next weekly run they existed
  -- only in that script, and check_corpus_census.ts failed outright reading a
  -- column no committed DDL declared. Declared here so the committed-DDL half
  -- of check_store_schema.py accounts for them.
  store                      TEXT NOT NULL DEFAULT 'unknown'::text,
  schema_state               JSONB
);
CREATE UNIQUE INDEX IF NOT EXISTS corpus_census_pkey ON corpus_census USING btree (id);
CREATE INDEX IF NOT EXISTS corpus_census_taken_idx ON corpus_census USING btree (taken_at DESC);

